// Go runner. Usage: runner <problem_dir> <cases.json> <iters> <warmup>
// See tools/lc/langs.py for the contract. Prints {"cases": [{"ns", "result"}]}.
//
// Your solutions live in problems/<id>/solution.go.
// problems/<id>/adapter_gen.go and registry/registry_gen.go are generated by `lc`.
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"strconv"
	"time"

	"lcbench/registry"
)

type caseResult struct {
	Ns     int64 `json:"ns"`
	Result any   `json:"result"`
}

func run() error {
	if len(os.Args) != 5 {
		return fmt.Errorf("usage: runner <problem_dir> <cases.json> <iters> <warmup>")
	}
	id := filepath.Base(os.Args[1])
	iters, _ := strconv.Atoi(os.Args[3])
	warmup, _ := strconv.Atoi(os.Args[4])

	prepare, ok := registry.Problems[id]
	if !ok {
		return fmt.Errorf("no Go registry entry for %s", id)
	}
	data, err := os.ReadFile(os.Args[2])
	if err != nil {
		return err
	}
	var cases []struct {
		Input map[string]json.RawMessage `json:"input"`
	}
	if err := json.Unmarshal(data, &cases); err != nil {
		return err
	}

	out := make([]caseResult, 0, len(cases))
	for _, c := range cases {
		times := make([]int64, 0, iters)
		var result any
		for i := 0; i < warmup+iters; i++ {
			call, err := prepare(c.Input) // fresh copy, not timed
			if err != nil {
				return err
			}
			start := time.Now()
			result = call()
			ns := time.Since(start).Nanoseconds()
			if i >= warmup {
				times = append(times, ns)
			}
		}
		slices.Sort(times)
		out = append(out, caseResult{Ns: times[len(times)/2], Result: result})
	}
	return json.NewEncoder(os.Stdout).Encode(map[string]any{"cases": out})
}

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
